local a={'qbox','qbcore','esx'}function Doctor.detectFramework(b)local c=Doctor.resources(b)local d={}for e,f in ipairs(a)do local g=Config.Frameworks[f]if g and c.set[g.core]then d[#d+1]={id=f,core=g.core,label=g.label,def=g,state=GetResourceState(g.core)}end end;return d end;Doctor.register({id='framework',title='Framework',run=function(b)local d=Doctor.detectFramework(b)if#d==0 then b:add({severity='informacion',title='No se detectó QBox, QBCore ni ESX',where='-',why='Se trata el servidor como independiente: solo se hacen las comprobaciones generales.',fix={'Si usas uno de esos frameworks con otro nombre de recurso, cámbialo en Config.Frameworks.'}})end;local h={}for e,g in ipairs(d)do local i=Doctor.isRunning(g.state)b:add({severity='informacion',title=('Framework detectado: %s (%s, %s)'):format(g.label,g.core,i and'iniciado'or g.state),where=g.core,why='',fix={}})if i then h[#h+1]=g else b:add({severity='advertencia',title=('%s está instalado pero no iniciado'):format(g.core),where=g.core,why=('Los recursos que dependen de %s no funcionarán mientras siga en estado "%s".'):format(g.label,g.state),fix={('Mira en la consola el mensaje de error al hacer "ensure %s".'):format(g.core),'Si no usas este framework, quítalo de la carpeta resources para evitar confusiones.'}})end;for e,j in ipairs(g.def.requires or{})do if not Doctor.isRunning(GetResourceState(j))then b:add({severity=i and'error'or'advertencia',title=('%s necesita %s y no está iniciado'):format(g.label,j),where='server.cfg',why=('%s depende de %s para funcionar.'):format(g.label,j),fix={('Instala %s y pon "ensure %s" antes de "ensure %s".'):format(j,j,g.core)}})end end end;if#d>1 then local k={}for e,g in ipairs(d)do k[#k+1]=g.core end;b:add({severity='advertencia',title='Hay varios frameworks instalados',where=table.concat(k,', '),why=(#h>1 and'Están iniciados a la vez. 'or'')..'Muchos scripts eligen el framework buscando cuál existe y pueden escoger el que no usas.',fix={'Deja solo el framework que usas y quita los demás de la carpeta resources.'}})end;local l=h[1]if l and l.id=='qbox'and GetConvar('onesync','off')=='off'then b:add({severity='error',title='QBox necesita OneSync y está desactivado',where='server.cfg (onesync)',why='Sin OneSync, QBox y muchos de sus recursos no funcionan bien.',fix={'Arranca el servidor con "+set onesync on" (o actívalo en txAdmin).'}})end;if l and Doctor.isRunning(GetResourceState('ox_inventory'))and l.def.inventoryConvar then local m=GetConvar('inventory:framework','esx')if m~=l.def.inventoryConvar then b:add({severity=m=='esx'and'error'or'advertencia',title=('ox_inventory está configurado para "%s" y el framework es %s'):format(m,l.label),where='server.cfg (inventory:framework)',why='El inventario no cargará bien a los jugadores si habla con otro framework.',fix={('Añade "setr inventory:framework \'%s\'" a server.cfg antes de "ensure ox_inventory".'):format(l.def.inventoryConvar)}})end end;if Config.CheckDatabaseConvar and Doctor.isRunning(GetResourceState('oxmysql'))then local n=GetConvar('mysql_connection_string','')==''if n then b:add({severity='error',title='oxmysql no tiene datos de conexión',where='server.cfg (mysql_connection_string)',why='Sin ellos, todo lo que guarda en la base de datos (personajes, inventarios, vehículos) falla.',fix={'Añade set mysql_connection_string "mysql://usuario:contraseña@localhost/basedatos" con tus datos.','Guárdala en un archivo aparte (por ejemplo, uno que cargues con exec) y no lo compartas nunca.'}})end end end})